import type { MatchPlayer, PlayerHoleScore, PlayerId } from '../contracts/game';
import type { MatchStanding } from './types';

export class ScoreManager {
  createHoleScore(playerId: PlayerId, holeId: string): PlayerHoleScore {
    return { playerId, holeId, strokes: 0, completed: false, penaltyStrokes: 0 };
  }
  recordStroke(score: PlayerHoleScore): PlayerHoleScore { return { ...score, strokes: score.strokes + 1 }; }
  addPenalty(score: PlayerHoleScore, amount = 1): PlayerHoleScore {
    if (!Number.isInteger(amount) || amount < 0) throw new Error('Penalty must be a non-negative integer');
    return { ...score, strokes: score.strokes + amount, penaltyStrokes: score.penaltyStrokes + amount };
  }
  complete(score: PlayerHoleScore, completionTimeMs?: number): PlayerHoleScore {
    return { ...score, completed: true, completionTimeMs };
  }
  applyStrokeLimit(score: PlayerHoleScore, strokeLimit: number): PlayerHoleScore {
    if (!Number.isInteger(strokeLimit) || strokeLimit < 1) throw new Error('Stroke limit must be a positive integer');
    if (score.completed || score.strokes < strokeLimit) return score;
    return { ...score, completed: true };
  }
  parLabel(strokes: number, par: number): string {
    const delta = strokes - par;
    if (strokes === 1) return 'HOLE IN ONE';
    if (delta <= -3) return 'ALBATROSS';
    if (delta === -2) return 'EAGLE';
    if (delta === -1) return 'BIRDIE';
    if (delta === 0) return 'PAR';
    if (delta === 1) return 'BOGEY';
    if (delta === 2) return 'DOUBLE BOGEY';
    return `+${delta}`;
  }
  totalForPlayer(player: MatchPlayer): number {
    return player.holeScores.reduce((sum, score) => sum + score.strokes, 0);
  }
  standings(players: readonly MatchPlayer[]): MatchStanding[] {
    const rows = players.map(player => ({
      playerId: player.id,
      totalStrokes: this.totalForPlayer(player),
      completedHoles: player.holeScores.filter(score => score.completed).length,
      penaltyStrokes: player.holeScores.reduce((sum, score) => sum + score.penaltyStrokes, 0),
      completionTimeMs: player.holeScores.reduce((sum, score) => sum + (score.completionTimeMs ?? 0), 0),
      rank: 0,
    }));
    rows.sort((a, b) => a.totalStrokes - b.totalStrokes || b.completedHoles - a.completedHoles || a.penaltyStrokes - b.penaltyStrokes || a.completionTimeMs - b.completionTimeMs || a.playerId.localeCompare(b.playerId));
    rows.forEach((row, index) => { row.rank = index + 1; });
    return rows;
  }
}
