import type { MatchDTO, PlayerId } from '../contracts/game';

export class TurnManager {
  firstEligiblePlayer(match: MatchDTO, holeId: string): PlayerId | undefined {
    return match.players.find(player => player.connected && !player.holeScores.find(score => score.holeId === holeId)?.completed)?.id;
  }
  nextEligiblePlayer(match: MatchDTO, holeId: string, currentPlayerId: PlayerId): PlayerId | undefined {
    const eligible = match.players.filter(player => player.connected && !player.holeScores.find(score => score.holeId === holeId)?.completed);
    if (eligible.length === 0) return undefined;
    const currentIndex = eligible.findIndex(player => player.id === currentPlayerId);
    if (currentIndex < 0) return eligible[0]?.id;
    return eligible[(currentIndex + 1) % eligible.length]?.id;
  }
  allPlayersFinishedHole(match: MatchDTO, holeId: string): boolean {
    return match.players.every(player => player.holeScores.find(score => score.holeId === holeId)?.completed === true);
  }
}
